export function create(input, ctx) {
  const [author] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${input.author_id}`);
  if (!author) {
    ctx.reject({ message: `author ${input.author_id} does not exist`, pointer: "/author_id", hint: "Create the author first with POST /authors." });
  }
  const published = input.published === true;
  if (published && !author.name) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or create the book unpublished." });
  }
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  const [book] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  if ("author_id" in input) {
    const [author] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${input.author_id}`);
    if (!author) {
      ctx.reject({ message: `author ${input.author_id} does not exist`, pointer: "/author_id", hint: "Create the author first with POST /authors." });
    }
  }
  const authorId = "author_id" in input ? input.author_id : book.author_id;
  const published = "published" in input ? input.published : book.published;
  if (published) {
    const [author] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
    if (!author || !author.name) {
      ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or unpublish the book." });
    }
  }
  if ("title" in input) {
    ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  }
  if ("author_id" in input) {
    ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  }
  if ("published" in input) {
    ctx.db.exec(ctx.sql`UPDATE book SET published = ${input.published} WHERE id = ${ctx.id}`);
  }
}

