export default async function query(ctx: QueryContext) {
  const res = await ctx.fetch("http://127.0.0.1:18090/quotes.json");
  const rows = (await res.json()).map((q) => ({ id: q.id, text: q.quote, author: q.by }));
  if (ctx.operation === "item") return rows.find((r) => r.id === ctx.id) ?? null;
  let matches = rows;
  if (ctx.filters.author !== undefined) matches = rows.filter((r) => r.author === ctx.filters.author);
  const start = (ctx.page - 1) * ctx.itemsPerPage;
  return { items: matches.slice(start, start + ctx.itemsPerPage), totalItems: matches.length };
}

